        """Map a light-client error category to its HTTP status and body."""
        return HISTORY_ERROR_STATUS.get(category, 500), {"ok": False, "error": category}

    def _history_heads(self) -> tuple[str | None, str | None]:
        """Strictly load both history files' heads; category on any defect.

        Must be called with the store lock held (which also covers the
        per-path file locks). Returns ``(history_head, trust_head)`` (each None
        when the file is absent) or raises :class:`HistoryAccessError`.
        """
        from . import light_client

        trust_path = self.store.history_trust_path
        history_path = self.store.history_path
        assert trust_path is not None and history_path is not None
        try:
            _, trust_head = light_client.history_trust_head(trust_path)
            history_head = light_client.history_head(
                light_client.history_sidecar_path(history_path)
            )
        except light_client._CheckpointError as failure:
            raise HistoryAccessError(failure.category) from None
        return history_head, trust_head

    def _record_history_access(
        self, action: str, history_head: str | None, trust_head: str | None
    ) -> dict:
        """Append a history_access event, record heads and persist atomically.

        The external files, the audit event, the checkpoint and the generation
        all commit in the same critical section: the external file bytes are
        already on disk when this is called; the snapshot is then written and,
        on any failure, the in-memory audit/generation changes are rolled back
        (the external bytes are restored by the caller when it mutated them).
        Returns the appended event.
        """
        event = self.store.append_audit_event(
            EVENT_HISTORY_ACCESS,
            {
                "action": action,
                "trust_head": trust_head,
                "history_head": history_head,
            },
